function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function createAncestry() {
  return {
    id: genId(),
    name: '',
    rarity: 'common',
    unisexFirstNames: false,
    hasLastNames: true,
    firstNames: [],
    maleFirstNames: [],
    femaleFirstNames: [],
    lastNames: [],
  };
}

function createArea() {
  return { id: genId(), name: '', weights: {} };
}

// Name entries can be a plain string (legacy) or {en, he}. These read either.
function entryEN(e) {
  return e && typeof e === 'object' ? e.en : e;
}
function entryHE(e) {
  return e && typeof e === 'object' ? e.he || e.en : e;
}

function linesToEntries(text, oldArr) {
  const oldMap = {};
  (oldArr || []).forEach((e) => {
    oldMap[entryEN(e)] = e;
  });
  return (text || '')
    .split('\n')
    .map((s) => s.trim())
    .filter((s) => s.length > 0)
    .map((s) => oldMap[s] || { en: s, he: s });
}

function arrayToLines(arr) {
  return (arr || []).map(entryEN).join('\n');
}

function pickRandom(arr) {
  if (!arr || arr.length === 0) return null;
  return arr[Math.floor(Math.random() * arr.length)];
}

function rollGender() {
  return Math.random() < 0.5 ? 'male' : 'female';
}

function capitalize(s) {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}

function round(n) {
  return Math.round(n * 100) / 100;
}

function weightedPickAncestry(area, settings) {
  const weights = (area && area.weights) || {};
  const entries = settings.ancestries
    .map((a) => ({ ancestry: a, weight: parseFloat(weights[a.id]) || 0 }))
    .filter((e) => e.weight > 0);
  const total = entries.reduce((s, e) => s + e.weight, 0);
  if (total <= 0) return null;
  let r = Math.random() * total;
  for (const e of entries) {
    r -= e.weight;
    if (r < 0) return e.ancestry;
  }
  return entries[entries.length - 1].ancestry;
}

function rollName(ancestry, gender) {
  let firstEntry;
  if (ancestry.unisexFirstNames) {
    firstEntry = pickRandom(ancestry.firstNames);
  } else {
    firstEntry = pickRandom(gender === 'male' ? ancestry.maleFirstNames : ancestry.femaleFirstNames);
  }
  const lastEntry = ancestry.hasLastNames ? pickRandom(ancestry.lastNames) : null;
  return { firstEntry, lastEntry };
}

